export const normalize=s=>s.replaceAll('\r\n','\n').replaceAll('github.com/vkhanhqui/figma-mcp-go','github.com/Chammy01/figma-designer-mcp').replaceAll('with figma-mcp-go','with Figma Designer MCP').replaceAll('Starting figma-mcp-go (Tharun)','Starting Figma Designer MCP').replaceAll('figma-mcp-go-tharun','figma-designer-mcp').replace('const PLUGIN_VERSION = "1.3.0"; // bumped when toolkit overhaul lands','const PLUGIN_VERSION = "1.0.0"; // Owned product identity; capability behavior unchanged').replaceAll('https://github.com/tharuneswarj','https://github.com/Chammy01/figma-designer-mcp').replaceAll("Tharun's Figma MCP",'Figma Designer MCP · Chammy01').replaceAll('          Fork','          Upstream').replaceAll('Figma MCP — Tharun','Figma Designer MCP');
